using System;using System.Linq;using UnityEngine;using UnityEditor;using Resonator.AI;
public static class InspectGraphPose {public static object Run(){var go=UnityEngine.Object.Instantiate(AssetDatabase.LoadAssetAtPath<GameObject>("Assets/Game/Enemies/Resonator/AI/Prefabs/ResonatorAgent.prefab"));var e=go.GetComponent<ResonatorEnemy>();e.enabled=false;e.Initialize(RestActivity.SlowIdle);var arm=go.GetComponentsInChildren<Transform>().First(t=>t.name=="ValveBiped.Bip01_L_UpperArm");e.motion.Play(e.tuning.run,10,true);var playable=arm.localRotation;var hip=e.motion.hips.localRotation;foreach(var rb in e.ragdoll.bodies)rb.interpolation=RigidbodyInterpolation.None;e.motion.Play(e.tuning.run,10,true);var noInterpolation=arm.localRotation;e.tuning.run.track.clip.SampleAnimation(e.motion.gameObject,10/30f);var direct=arm.localRotation;var d=new{playable=playable.ToString(),noInterpolation=noInterpolation.ToString(),direct=direct.ToString(),difference=Quaternion.Angle(playable,direct),diffNoInterp=Quaternion.Angle(noInterpolation,direct),hip=hip.ToString(),animator=e.motion.animator.enabled};UnityEngine.Object.DestroyImmediate(go);return d;}}
